exports.main = async (event) => {
  // Initialize the model if it hasn't been loaded yet
  if (!model) {
    try {
      model = await loadModel();
      console.log('Model loaded successfully');
    } catch (error) {
      console.error('Error loading model:', error);
      return {
        statusCode: 500,
        body: JSON.stringify({ error: 'Model loading failed' })
      };
    }
  }

  try {
    // Parse the request body
    const body = JSON.parse(event.body);

    // Extract the input value
    const x = body.x;

    // Validate input
    if (typeof x !== 'number' || isNaN(x)) {
      return {
        statusCode: 400,
        body: JSON.stringify({ error: 'Invalid input: x must be a number' })
      };
    }

    // Make prediction
    const prediction = predict(model, x);

    // Return the response
    return {
      statusCode: 200,
      body: JSON.stringify({ prediction: prediction })
    };
  } catch (error) {
    console.error('Error processing request:', error);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: 'Internal server error' })
    };
  }
};
